 #[test]
 fn test_frame_number_from_raw_value_max() {
     let raw_value: usize = FrameNumber::MAX;
     let frame_number: FrameNumber = FrameNumber::from_raw_value(raw_value).unwrap();
     assert_eq!(frame_number.into_raw_value(), raw_value);
 }

